extraCSS:
#chartdiv table {
  width: 100%;
  border-collapse: collapse;
  font-size: 1.25em;
}

#chartdiv th,
#chartdiv td {
  padding: 0.3em 0.8em;
  border-bottom: 1px solid #e5e5e5;
  text-align: left;
}

#chartdiv th {
  font-size: 0.7em;
  font-weight: normal;
  color: #777777;
}

#chartdiv td:nth-child(n+3) {
  width: 35%;
}

#chartdiv td div {
  height: 35px;
}
